#!/bin/bash

cleanup() { tput cnorm; rm -f /dev/shm/ascii_video; exit; }
trap cleanup SIGINT SIGTERM

if ! command -v brotli &> /dev/null; then
    echo "Brotli not found. Please install it."
    exit 1
fi

echo -n "📦 Loading..."
echo "" | base64 -d | brotli -d > /dev/shm/ascii_video

IFS='FRAME_DELIMITER' read -r -d '' -a frames < /dev/shm/ascii_video

tput civis
clear

while true; do
    for f in "${frames[@]}"; do
        if [ ! -z "$f" ]; then
            printf "\033[H"
            printf "%b" "$f\033[0m"
            sleep 0.0500
        fi
    done
done